#include <stdint.h>
#include <string.h>
/* mnemonic secp256r1.mult -> secp256r1_mult_model; in[0..7]=A, in[8..15]=B, out[0..15]=A*B */
void secp256r1_mult_model(const uint32_t in[16], uint32_t out[16]) {
    uint32_t r0 = 0, r1 = 0, r2 = 0;
    int k, i;
    for (k = 0; k < 15; k++) {
        for (i = 0; i < 8; i++) {
            int j = k - i;
            if (j >= 0 && j < 8) {
                uint64_t p = (uint64_t)in[i] * (uint64_t)in[8 + j];
                uint64_t lo = (uint64_t)r0 + (uint64_t)(uint32_t)p;
                uint64_t hi = (uint64_t)r1 + (p >> 32) + (lo >> 32);
                r0 = (uint32_t)lo;
                r1 = (uint32_t)hi;
                r2 = r2 + (uint32_t)(hi >> 32);
            }
        }
        out[k] = r0;
        r0 = r1;
        r1 = r2;
        r2 = 0;
    }
    out[15] = r0;
}

#include <stdint.h>
#include <string.h>
/* mnemonic secp256r1.mmod -> secp256r1_mmod_model; in[0..15]=512-bit X, out[0..7]=X mod p256, out[8..15]=0 */
static const uint32_t MM_P256[8] = {0xFFFFFFFFu, 0xFFFFFFFFu, 0xFFFFFFFFu, 0x00000000u,
                                    0x00000000u, 0x00000000u, 0x00000001u, 0xFFFFFFFFu};
static int64_t mm_carry(int64_t acc, uint32_t *w) {
    uint32_t lo = (uint32_t)((uint64_t)acc);
    *w = lo;
    return (acc - (int64_t)lo) / (int64_t)4294967296LL;
}
static int64_t mm_fold(uint32_t w[8], int64_t t) {
    int64_t c = 0;
    c = mm_carry((int64_t)w[0] + c + t, &w[0]);
    c = mm_carry((int64_t)w[1] + c, &w[1]);
    c = mm_carry((int64_t)w[2] + c, &w[2]);
    c = mm_carry((int64_t)w[3] + c - t, &w[3]);
    c = mm_carry((int64_t)w[4] + c, &w[4]);
    c = mm_carry((int64_t)w[5] + c, &w[5]);
    c = mm_carry((int64_t)w[6] + c - t, &w[6]);
    c = mm_carry((int64_t)w[7] + c + t, &w[7]);
    return c;
}
void secp256r1_mmod_model(const uint32_t in[16], uint32_t out[16]) {
    int64_t c[16];
    int64_t col[8];
    uint32_t w[8], d[8];
    int64_t t;
    uint64_t b;
    uint32_t m;
    int i;
    for (i = 0; i < 16; i++) c[i] = (int64_t)in[i];
    col[0] = c[0] + c[8] + c[9] - c[11] - c[12] - c[13] - c[14];
    col[1] = c[1] + c[9] + c[10] - c[12] - c[13] - c[14] - c[15];
    col[2] = c[2] + c[10] + c[11] - c[13] - c[14] - c[15];
    col[3] = c[3] + 2 * c[11] + 2 * c[12] + c[13] - c[15] - c[8] - c[9];
    col[4] = c[4] + 2 * c[12] + 2 * c[13] + c[14] - c[9] - c[10];
    col[5] = c[5] + 2 * c[13] + 2 * c[14] + c[15] - c[10] - c[11];
    col[6] = c[6] + 3 * c[14] + 2 * c[15] + c[13] - c[8] - c[9];
    col[7] = c[7] + 3 * c[15] + c[8] - c[10] - c[11] - c[12] - c[13];
    t = 0;
    for (i = 0; i < 8; i++) t = mm_carry(col[i] + t, &w[i]);
    t = mm_fold(w, t);
    t = mm_fold(w, t);
    (void)t; /* provably 0 after the second fold */
    b = 0;
    for (i = 0; i < 8; i++) {
        uint64_t s = (uint64_t)w[i] - (uint64_t)MM_P256[i] - b;
        d[i] = (uint32_t)s;
        b = (s >> 32) & 1u;
    }
    m = (uint32_t)0 - (uint32_t)b; /* all-ones iff w < p: keep w */
    for (i = 0; i < 8; i++) out[i] = (w[i] & m) | (d[i] & ~m);
    for (i = 8; i < 16; i++) out[i] = 0;
}

#include <stdint.h>
#include <string.h>
/* mnemonic secp256r1.modsub -> secp256r1_modsub_model; in[0..7]=L, in[8..15]=R, out[0..7]=(L-R) mod p256, out[8..15]=0 */
static const uint32_t MS_P256[8] = {0xFFFFFFFFu, 0xFFFFFFFFu, 0xFFFFFFFFu, 0x00000000u,
                                    0x00000000u, 0x00000000u, 0x00000001u, 0xFFFFFFFFu};
void secp256r1_modsub_model(const uint32_t in[16], uint32_t out[16]) {
    uint32_t d[8];
    uint64_t b = 0, c = 0;
    uint32_t m;
    int i;
    for (i = 0; i < 8; i++) {
        uint64_t s = (uint64_t)in[i] - (uint64_t)in[8 + i] - b;
        d[i] = (uint32_t)s;
        b = (s >> 32) & 1u;
    }
    m = (uint32_t)0 - (uint32_t)b;
    for (i = 0; i < 8; i++) {
        uint64_t s = (uint64_t)d[i] + (uint64_t)(MS_P256[i] & m) + c;
        out[i] = (uint32_t)s;
        c = s >> 32;
    }
    for (i = 8; i < 16; i++) out[i] = 0;
}
